   {
    "quote": "For clusters that are being upgraded to 1.24 with kubeadm upgrade apply, the command will add the new taint node-role.kubernetes.io/control-plane:NoSchedule to existing control plane nodes.",
    "source": "Kubernetes v1.24.0 CHANGELOG",
    "release_of_change": "1.24"
   }
  ]
 },
